using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class HitPureCompactnessDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Incidence of every original pure label with every actual pure-pair face closes the entire pure locus.",
        H("Closedness and compactness from original face incidence"), Blocks(
            Describe.Lean(DescribeId.Create("hit-pure-closed-compact"),
                DeclarationHandle.Create("D5/S3/Quantum/Foundation/HitPureCompactness.hit_pure_closed_compact"),
                H("All-label Hit closes the original pure locus"),
                StatementSource.FromAuthor(Disp(Telescope(Implies(Hypotheses(),
                    And(Call("IsClosed", Pure()), Call("IsCompact", Pure())))))),
                AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Let V be a finite dimensional real normed vector space, C its original closed convex cone containing zero, and u its original real linear unit. Assume u(x)>0 for every nonzero x in C and span(C)=V. Set K=base(C,u) and P=pure(C,u)=ext(K). For every a in the entire original pure subtype, assume Hit(C,u,a): every actual face generated by two distinct original pure points meets neighbors(C,u,a). Then P is closed and compact. In particular this holds on the original nonzero pointed generating cone domain. The norm supplies the usual finite dimensional topology. No L2, LIN, SP, NC, reciprocity, closed pure carrier or finite pure decomposition is assumed.")),
                    Paragraph(Text("Take a sequence of original pure points converging to x in the compact original base. If x is not pure, use its actual principal face F, defined by positive domination. Closedness of F follows from the original face-span identity and finite dimension. Its normalized base is compact, and its extreme points are original pure points. Original Hit passes to F: the hit point lies in F, each original effect restricts to F, and a face of F is an original cone face by transitivity. Apply hit_section_generation to the full linear section of this face. Its finite convex-hull conclusion forces two distinct pure points in F whenever x is not pure. This uses base_eq_convexHull_pure through the section theorem, without assuming that the original pure set is closed.")),
                    Paragraph(Text("For every sequence label a(n), Hit now gives a pure neighbour b(n) in that fixed pair face, hence in F, with an original proper effect e(n) satisfying e(n)(a(n))=1 and e(n)(b(n))=0. Compactness of the entire original effect interval gives a convergent subsequence with limit e. Joint continuity of evaluation gives e(x)=1. For every b(n), principal_extension expresses x as a strictly positive convex combination of b(n) and another point of the same face. Both effect readings are at most one, so e(b(n))=1. A further subsequence of the b(n) converges in K; joint evaluation then makes its limiting reading zero, while continuity of e makes it one. This contradiction proves closedness. Closed containment in the compact original base proves compactness.")),
                    Paragraph(Text("The source is Quantum Origin Binary Normal Differences and Orientation XVII, Theorem 198.5. The argument concerns the entire original cone, pure locus, actual faces and full proper effect interval. It gives no classification, additional physical realization or literature-priority claim."))),
                DescribeRole.Theorem))));

    private static Formula Real() => Seq(Mathbb, Grp(F.Id("R")));
    private static Formula Call(string name, params Formula[] args) =>
        new Formula.Apply(new Formula.NamedConstant(FormulaIdentifier.Create(name)), [.. args]);
    private static Formula All(string name, Formula type, Formula body) =>
        new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(name), type, body);
    private static Formula And(Formula a, Formula b) =>
        new Formula.Logic(a, FormulaLogicOperator.And, b);
    private static Formula Implies(Formula a, Formula b) =>
        new Formula.Logic(a, FormulaLogicOperator.Implies, b);
    private static Formula Pure() => Call("pure", F.Id("C"), F.Id("u"));
    private static Formula Hypotheses() => And(Call("IsClosed", F.Id("C")), And(
        All("x", F.Id("V"), Implies(And(
            new Formula.Relation(F.Id("x"), FormulaRelationOperator.MemberOf, F.Id("C")),
            new Formula.Relation(F.Id("x"), FormulaRelationOperator.NotEqual, D(0))),
            new Formula.Relation(D(0), FormulaRelationOperator.LessThan, Call("u", F.Id("x"))))),
        And(new Formula.Relation(Call("span", Real(), F.Id("C")),
                FormulaRelationOperator.Equal, F.Id("top")),
            All("a", Pure(), Call("Hit", F.Id("C"), F.Id("u"), F.Id("a"))))));
    private static Formula Telescope(Formula body) => All("V", F.Id("Type"),
        Seq(OpenBracket, Call("NormedAddCommGroup", F.Id("V")), CloseBracket, Sp,
            OpenBracket, Call("NormedSpace", Real(), F.Id("V")), CloseBracket, Sp,
            OpenBracket, Call("FiniteDimensional", Real(), F.Id("V")), CloseBracket, Sp,
            All("C", Call("PointedCone", Real(), F.Id("V")),
                All("u", Call("LinearMap", Real(), F.Id("V"), Real()), body))));
}
